Function fabricada <- CrearSumador(cantidad As Integer)
  Define fabricada As Function(Integer) As Integer <- Function(x As Integer) As Integer
    Return x + cantidad;
  EndFunction;
EndFunction

Algorithm Sumar
  Define masTres As Function(Integer) As Integer <- CrearSumador(3);
  Write masTres(4);
EndAlgorithm

Function fabricada <- CrearDescuento(porcentaje As Integer)
  Define fabricada As Function(Integer) As Integer <- Function(precio As Integer) As Integer
    Return precio - precio * porcentaje Div 100;
  EndFunction;
EndFunction

Function nuevos <- Mapear(v As Vector<Integer>, f As Function(Integer) As Integer)
  Define nuevos As Vector<Integer> <- vector();
  For Each elemento In v Do
    nuevos.append(f(elemento));
  EndFor
EndFunction

Algorithm Campanas
  Define porcentaje As Integer;
  Read porcentaje;
  Define precios As Vector<Integer> <- vector();
  precios.append(50);
  precios.append(30);
  precios.append(20);
  Define descuento As Function(Integer) As Integer <- CrearDescuento(porcentaje);
  Write Mapear(precios, descuento);
EndAlgorithm
